{
  "name": "@dietrichgebert/ponytail",
  "version": "5.3.2",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "!pi-extension/test/",
    "scripts/uninstall.js",
    "scripts/cursor-hooks.js",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

{
	"name": "linkswift",
	"version": "1.1.3.1",
	"description": "一个基于 JavaScript 的网盘文件下载地址获取工具",
	"main": "eslint.config.js",
	"scripts": {
		"test": "echo \"Error: no test specified\" && exit 1",
		"check": "npx eslint . --fix"
	},
	"repository": {
		"type": "git",
		"url": "git+https://github.com/hmjz100/LinkSwift.git"
	},
	"keywords": [
		"linkswift",
		"link",
		"swift",
		"download",
		"file",
		"address",
		"get"
	],
	"author": "hmjz100",
	"license": "AGPL-3.0",
	"type": "commonjs",
	"bugs": {
		"url": "https://github.com/hmjz100/LinkSwift/issues"
	},
	"homepage": "https://github.com/hmjz100/LinkSwift#readme",
	"devDependencies": {
		"@eslint/js": "^10.0.1",
		"eslint": "^10.6.0"
	},
	"dependencies": {
		"@eslint/js": "^10.0.1",
		"eslint": "^10.6.0"
	}
}

{
  "name": "pstack",
  "private": true,
  "version": "0.9.102",
  "description": "If you want to go fast, go deep first. pstack helps you write less, but higher quality code. rigorous agent workflows you can parallelize with confidence. Pi package of the Claude Code plugin; skills are shared, tool names resolve via skills/poteto-mode/references/pi-tools.md. Original pstack by Lauren Tan (poteto).",
  "author": {
    "name": "Michael Denyer",
    "url": "https://github.com/michael-denyer"
  },
  "homepage": "https://github.com/michael-denyer/pstack-claude",
  "repository": "https://github.com/michael-denyer/pstack-claude",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "pstack",
    "poteto-mode",
    "workflow",
    "principles",
    "agent-style",
    "subagents",
    "unslop",
    "claude-code",
    "skills",
    "tdd",
    "code-review",
    "parallel-agents",
    "codex",
    "opencode",
    "gemini-cli",
    "prime-agent"
  ],
  "pi": {
    "skills": [
      "./plugins/pstack/skills"
    ],
    "extensions": [
      "./plugins/pstack/pi/index.ts"
    ]
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  }
}
